@@ -0,0 +1,13 @@
+import { createEventCard } from './event-card.js';
+
+export function sortChronologically(items) {
+  return items
+    .map((item) => ({ item, time: new Date(item.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time)
+    .map(({ item }) => item);
+}
+
+export function buildAgenda(events) {
+  const entries = events.map((event) => ({ card: createEventCard(event), startsAt: event.startsAt }));
+  return sortChronologically(entries).map(({ card }) => card);
+}

